{
  "reviews": [
    {
      "id": "B200-R7b-RANK-ROUTE-1",
      "criteria": {
        "required_improvement": {
          "verdict": "unknown",
          "score": 3,
          "rationale": "The proposal gives a cheap inspection gate and a testable route to value. Its delta from the running baseline remains unknown because the effective router policy and rank targeting have not been inspected. The PR author describes a path that is “Disabled by default,” but that does not establish this deployment’s state."
        },
        "causal_test": {
          "verdict": "pass",
          "score": 4,
          "rationale": "CPU-only shadow replay first asks whether eligible, resident exact prefixes are being missed. The later one-factor replay compares routing against R7b and a tuned static policy on held-out distributions, measuring served rank-local hits, skew, latency, and frozen length-aware goodput. The 75% cacheability target is correctly kept separate from observed hits."
        },
        "integration_and_bounds": {
          "verdict": "unknown",
          "score": 3,
          "rationale": "The proposed API2-to-DP4 rank decision and load-only fallback address the required integration. Actual rank targeting is unverified. “Chosen skew limit” needs an explicit queue-load measure and enforcement rule before the bound is reviewable."
        },
        "claim_discipline": {
          "verdict": "pass",
          "score": 4,
          "rationale": "The c384 and c512 figures are identified as supplied baseline results, not evidence of cache misses. The PR author says the path “Only supports internal/local DP load balancing”; that is an author claim, not verified running behavior. CacheRoute’s warning that “affinity can reduce capacity when the recoverable prefix work is small” supports a transfer risk, not a B200 effect estimate."
        }
      },
      "factual_support": "pass",
      "objections": [
        "Effective image, router policy, API2 rank propagation, and exact resident-prefix hit rate are unknown.",
        "The supplied routing PR body and documentation PR do not establish deployed code or serving gains.",
        "A routing choice alone is not a served cache hit; the proposed instrumentation must verify residency and use."
      ],
      "required_revision": "Inspect the effective deployment first. Define the skew metric, cap, and load-only trigger; then retain the proposed shadow and held-out one-factor comparisons."
    },
    {
      "id": "B200-R7b-PREFILL-ADMIT-1",
      "criteria": {
        "required_improvement": {
          "verdict": "unknown",
          "score": 3,
          "rationale": "The scheduler inspection gate and trace question give a credible testable path. Whether an adaptive admission policy is absent, or prefill interferes with decode on this deployment, remains unknown. The supplied E2E results do not settle either question."
        },
        "causal_test": {
          "verdict": "pass",
          "score": 4,
          "rationale": "The cheapest check asks whether prefill-bearing iterations coincide with decode deadline misses and separates preemption as an alternative. Association alone would not establish cause; the proposed one-factor held-out replay against R7b and tuned static controls provides the causal comparison. It includes TTFT, waiting, starvation, and output-length cohort metrics."
        },
        "integration_and_bounds": {
          "verdict": "unknown",
          "score": 3,
          "rationale": "Scheduler-local admission, a fixed global token budget, a maximum wait, and fixed-budget fallback are plausible. The RFC author states, “The global scheduler token budget remains unchanged.” The actual V1 scheduler path is unverified, and the proposal must define how forced prefill progress interacts with a simultaneous decode deadline before its bounds are assessable."
        },
        "claim_discipline": {
          "verdict": "pass",
          "score": 4,
          "rationale": "The RFC’s “reduced average end-to-end latency by 8.5%” is presented as an author report from other configurations, with no B200 speedup prediction. The supplied paper says the effect “depends on the model–hardware configuration,” and another flags that “starvation and admission control deserve separate study.” Neither passage verifies this deployment’s implementation."
        }
      },
      "factual_support": "pass",
      "objections": [
        "Adaptive feature presence, decode deadline misses, TTFT, starvation, and B200 effect size are unknown.",
        "A trace association is only a falsification screen; preemption and KV pressure remain alternative causes.",
        "The static comparator should be chosen under the same frozen scorer and stated eligibility rules; the wait bound and fallback priority need precise definitions."
      ],
      "required_revision": "Inspect the effective scheduler and timing telemetry. Specify the maximum wait, decode deadline rule, and conflict fallback; then compare independently with the strongest eligible static policy on held-out replay."
    }
  ],
  "global_gaps": [
    "The desired engine profile is not verified runtime state. The reported c384 and c512 results do not identify either proposed bottleneck.",
    "No supplied source establishes a B200 effect size. PR and RFC implementation descriptions are author claims; quoted paper limitations do not serve as implementation evidence.",
    "The length-aware scorer and output-length cohorts must be frozen. Whole-trace inter-token-gap p95 must remain distinct from per-request TPOT.",
    "No GPU work is proposed for this research session; the bounded GPU replays described are later experiments."
  ]
}
